(() => {
const layer=document.getElementById('effects'),wait=ms=>new Promise(r=>setTimeout(r,ms));
function enabled(){return window.gameDebug?.animate()}
function at(el,p){el.style.left=(p.x+.5)*64+'px';el.style.top=(p.y+.5)*64+'px';layer.append(el);return el}
function emit(p,cl,text,duration=850){const el=document.createElement('span');el.className=cl;if(text!==undefined)el.textContent=text;at(el,p);setTimeout(()=>el.remove(),duration);return el}
function step(p,duration){const el=window.gameDebug.getPiece(p.id);if(!el)return;el.style.transition=duration?'left '+duration+'ms cubic-bezier(.22,.61,.36,1), top '+duration+'ms cubic-bezier(.22,.61,.36,1)':'none';if(duration){el.firstChild.classList.remove('step-bob');void el.offsetWidth;el.firstChild.classList.add('step-bob');setTimeout(()=>el.firstChild?.classList.remove('step-bob'),duration)}}
async function strike(a,b,animate=true){if(!animate)return;const el=window.gameDebug.getPiece(a.id),dx=Math.sign(b.x-a.x),dy=Math.sign(b.y-a.y);if(el){el.style.setProperty('--dx',dx*12+'px');el.style.setProperty('--dy',dy*12+'px');el.firstChild.classList.add('strike');setTimeout(()=>el.firstChild?.classList.remove('strike'),300)}if(Math.abs(a.x-b.x)+Math.abs(a.y-b.y)>1){const shot=emit(a,'projectile',undefined,350);shot.style.setProperty('--tx',(b.x-a.x)*64+'px');shot.style.setProperty('--ty',(b.y-a.y)*64+'px');await wait(230)}else await wait(145)}
function impact(p,amount,critical=false,animate=true,type='damage'){const el=window.gameDebug.getPiece(p.id);if(el&&animate){el.firstChild.classList.remove('hurt');void el.offsetWidth;el.firstChild.classList.add('hurt');setTimeout(()=>el.firstChild?.classList.remove('hurt'),360)}const number=emit(p,'damage-number '+type+(critical?' critical':'')+(!animate?' no-motion':''),typeof amount==='number'?'−'+amount:amount,1100);if(critical)number.setAttribute('aria-label','Критический удар '+amount);if(animate){emit(p,'impact-ring '+type,undefined,500);if(typeof amount==='number')for(let i=0;i<5;i++){const spark=emit(p,'hit-spark',undefined,480);spark.style.setProperty('--sx',Math.cos(i*1.26)*25+'px');spark.style.setProperty('--sy',Math.sin(i*1.26)*25+'px')}}}
function pulse(p){emit(p,'impact-ring heal',undefined,600)}
function door(p){const node=document.querySelector(`.prop[data-id="${p.id}"]`);node?.classList.add('door-opening');setTimeout(()=>node?.classList.remove('door-opening'),450)}
let last=0;function loop(t){if(t-last>750&&enabled()&&!document.hidden&&!document.getElementById('map-view').hidden){last=t;for(const light of window.gameDebug.scene.lights.filter(l=>l.id!=='altar')){const e=emit({x:light.x-.5,y:light.y-.85},'ember',undefined,1500);e.style.setProperty('--drift',Math.sin(t*.001+light.phase)*12+'px')}}window.requestAnimationFrame(loop)}if(window.requestAnimationFrame)window.requestAnimationFrame(loop);
window.fx={step,strike,impact,pulse,door};
})();
